async function showComparison(triangles:any,asset?:Asset,materials?:any,comparison?:any,diagnostics?:any){
 const previewSource=sourcePreview?{...sourcePreview,scale:asset?.source?.options?((asset.source.options as any).scale??1):Number(($('import-scale') as HTMLInputElement)?.value??1),upAxis:asset?.source?.options?((asset.source.options as any).upAxis??'Y'):(($('import-up') as HTMLSelectElement)?.value??'Y')}:undefined;
 await viewer.showComparison(triangles,asset,materials,previewSource);$('projection').textContent='透视';($('view-direction') as HTMLSelectElement).value='perspective';$('viewport-title').textContent=asset?`原件（左） / 体素结果（右） · ${asset.cellSize} m`:'导入原件 · 尚未体素化';$('view-label').textContent='IMPORT COMPARE';$('viewport-size').textContent='临时预览 · 尚未入库';
 const g=asset?new Grid(asset.chunks):null,b=g?.bounds(),d:any=diagnostics??asset?.source?.diagnostics,c=comparison??(asset&&b?{voxelDimensionsM:b.max.map((n,i)=>(n-b.min[i])*asset.cellSize),occupiedVolumeM3:g!.count*asset.cellSize**3,voxels:g!.count}:{});
 $('inspector').innerHTML=`<section class="section"><h2>导入检查与对照</h2><p class="subtle" style="margin-top:15px">原件在左，体素结果在右。预览不改变当前项目；确认提交后才加入母版库。</p><button id="leave-comparison" style="width:100%;margin-top:15px">返回项目编辑</button></section><section class="section"><h3>结果尺寸 / 体积 / 细节损失</h3><pre class="report">${esc(JSON.stringify(c,null,2))}</pre></section><section class="section"><h3>源几何诊断</h3><pre class="report">${esc(JSON.stringify(d??{},null,2))}</pre></section>`;
 $('leave-comparison').onclick=()=>safe(()=>setMode(viewMode,activeAsset));
}
(window as any).showVoxelComparison=showComparison;
