const appState={clay:(v:boolean)=>{viewer.setClay(v);$('clay').classList.toggle('active',v);$('material-view').classList.toggle('active',!v);for(const id of['studio','reference-light','ao','bloom','practicals'])($<HTMLButtonElement>(id)).disabled=v;},get clayEnabled(){return viewer.clayEnabled;},ao:(v:boolean)=>{viewer.aoEnabled=v;$('ao').classList.toggle('active',v);},studio:(v:boolean)=>{viewer.setStudio(v);$('studio').classList.toggle('active',v);},referenceLighting:(v:boolean)=>{viewer.setReferenceLighting(v);$('reference-light').classList.toggle('active',v);},bloom:(v:boolean)=>{viewer.bloomEnabled=v;$('bloom').classList.toggle('active',v);},practicals:(v:boolean)=>{viewer.practicalsEnabled=v;viewer.practicalLights.visible=v&&viewer.studio;$('practicals').classList.toggle('active',v);},get ready(){return viewer.ready&&!!project;},get version(){return project?.version;},get project(){return project;},view:(name:string)=>changeView(name),mode:async(mode:'scene'|'asset',id?:string)=>setMode(mode,id),clip:(value:number)=>viewer.setClip(value),focus:(region:Bounds)=>viewer.focusRegion(region),isolate:async(region:Bounds|null)=>{await viewer.isolateRegion(region);renderInspector();updateViewInfo();},get performance(){return{renderedVersion:viewer.renderedVersion,assetIds:[...new Set(viewer.root.children.flatMap(g=>g.children.map(m=>m.userData.assetId)))],frameIntervalsMs:[...viewer.frameTimes],drawCalls:viewer.renderer.info.render.calls,triangles:viewer.renderer.info.render.triangles,objects:viewer.root.children.reduce((s,g)=>s+g.children.length,0),lastWorkerMeshMs:viewer.lastMeshMs,meshedAssetIds:[...viewer.lastMeshedAssets],meshJobs:viewer.meshJobs,cachedAssetIds:[...viewer.cache.keys()],geometryBytes:viewer.geometryBytes,meshError:viewer.lastMeshError,isolatedRegion:viewer.isolatedRegion};}};(window as any).voxelStudio=appState;
