function transformDialog(kind:string){const a=project.assets[activeAsset],b=localSelection??new Grid(a.chunks).bounds();if(!b)return toast('资产没有体素');
 modal(({move:'移动选区',rotate:'旋转选区',mirror:'镜像选区',copy:'复制选区',array:'阵列选区',extrude:'挤出选区'})[kind]??kind,`<p>变换作用于母版格子。整数格坐标，旋转为 90° 的整数倍。目标冲突默认中止。</p><div class="field-stack"><label>轴<select id="tr-axis"><option value="0">X</option><option value="1" selected>Y</option><option value="2">Z</option></select></label><label>位移 / 阵列步长 X Y Z（格）</label><div class="triple">${[kind==='copy'||kind==='array'?b.max[0]-b.min[0]+2:1,0,0].map((v,i)=>`<input id="tr-${i}" type="number" step="1" value="${v}">`).join('')}</div><label>${kind==='extrude'?'挤出格数':'阵列总新增份数'}<input id="tr-count" type="number" min="1" max="100" value="${kind==='array'?3:1}"></label><label>覆盖相撞格子<input id="tr-overwrite" type="checkbox"></label></div>`,[{label:'取消',action:closeModal},{label:'预览变换',primary:true,action:async()=>{
 const v=[0,1,2].map(i=>Number(($('tr-'+i) as HTMLInputElement).value)),axis=Number(($('tr-axis') as HTMLSelectElement).value),count=Number(($('tr-count') as HTMLInputElement).value),overwrite=($('tr-overwrite') as HTMLInputElement).checked;let cmd:Command={op:'transform',assetId:a.id,region:b,overwrite};
 if(kind==='move')cmd.translation=v;if(kind==='rotate')cmd.rotation={axis,quarterTurns:1};if(kind==='mirror')cmd.mirror=axis;if(kind==='copy')Object.assign(cmd,{copy:true,translation:v});if(kind==='array')Object.assign(cmd,{copy:true,translation:v,step:v,count});if(kind==='extrude'){const direction=[0,0,0];direction[axis]=1;cmd={op:'extrude',assetId:a.id,region:b,direction,distance:count};}
 closeModal();await edit([cmd],'选区'+kind,true);
 }}]);}
document.querySelectorAll<HTMLButtonElement>('[data-tool]').forEach(el=>el.onclick=()=>safe(async()=>{const kind=el.dataset.tool!;if(kind!=='orbit'&&viewMode!=='asset')await setMode('asset');if(['move','rotate','mirror','copy','array','extrude'].includes(kind))return transformDialog(kind);if(kind==='fill')return edit([{op:'voxels',assetId:activeAsset,mode:'fill',region:readRegion(),material:activeMaterial}],'区域填充',true);viewer.setTool(kind);document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b===el));boxStart=null;}));
viewer.onPick=(voxel,normal,assetId,instanceId,event)=>{
 if(viewMode==='scene'){if(instanceId){selectedInstance=instanceId;activeAsset=assetId!;renderInspector();renderLeft();if(project.selection.assetId!==assetId)void safe(()=>edit([{op:'select',assetId,region:null,partId:null}],'选择实例母版'));}return;}if(!voxel||!normal||!assetId||busy)return;
 if(viewer.tool==='pick'){activeMaterial=new Grid(project.assets[assetId].chunks).get(voxel)||activeMaterial;renderInspector();return;}
 if(viewer.tool==='box'){if(!boxStart){boxStart=voxel;toast('已选择第一角，再点击对角');}else{const region={min:voxel.map((v,i)=>Math.min(v,boxStart![i])) as V3,max:voxel.map((v,i)=>Math.max(v,boxStart![i])+1) as V3};boxStart=null;void safe(()=>edit([{op:'select',assetId,region,partId:null}],'框选'));}return;}
 if(viewer.tool==='brush'||viewer.tool==='erase'){strokeAsset=assetId;strokeMode=viewer.tool==='brush'?'add':'remove';stroke=[viewer.tool==='brush'?voxel.map((n,i)=>n+normal[i]) as V3:voxel];isPainting=true;}
};
viewer.onDrag=(p,event)=>{if(p)$('coord').textContent=`格 ${p.join(' , ')}`;if(isPainting&&p&&(event.buttons&1)){let v=p;if(viewer.tool==='erase'){const hit=viewer.pick(event);if(hit)v=hit.voxel;}if(!stroke.some(c=>c.every((n,i)=>n===v[i])))stroke.push(v);}};
window.addEventListener('pointerup',()=>{if(!isPainting)return;isPainting=false;const cells=stroke;stroke=[];const cmd:Command={op:'voxels',assetId:strokeAsset,mode:strokeMode,cells,material:activeMaterial};if(symmetryAxes.length){const b=localSelection??new Grid(project.assets[strokeAsset].chunks).bounds()??{min:[0,0,0],max:[0,0,0]};cmd.symmetry={axes:symmetryAxes,pivot:b.min.map((n,i)=>Math.round((n+b.max[i])/2))};}void safe(()=>edit([cmd],strokeMode==='add'?'笔刷添加':'笔刷擦除'));});
