let clipped=false;$('clip').onclick=()=>{clipped=!clipped;if(clipped&&viewMode==='asset'){const b=viewer.contentBounds();($('clip-height') as HTMLInputElement).value=String(Number(((b.min.y+b.max.y)/2).toFixed(3)));}viewer.setClip(clipped?Number(($('clip-height') as HTMLInputElement).value):100);$('clip').classList.toggle('active',clipped);$('clip-options').classList.toggle('hidden',!clipped);};$('clip-height').oninput=()=>{const y=Number(($('clip-height') as HTMLInputElement).value);if(Number.isFinite(y)&&clipped)viewer.setClip(y);};
$('undo').onclick=()=>safe(()=>edit([{op:'undo'}],'撤销'));$('redo').onclick=()=>safe(()=>edit([{op:'redo'}],'重做'));
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!(e.target instanceof HTMLInputElement)){e.preventDefault();void safe(()=>edit([{op:e.shiftKey?'redo':'undo'}],e.shiftKey?'重做':'撤销'));}if(e.key==='Escape'){closeModal();viewer.setTool('orbit');isPainting=false;}});
$('save').onclick=()=>modal('项目另存为',`<p>原生格式完整保存体素、材质、部件、接口与实例。文件写入限定的本地项目目录。</p><label>文件名<input id="save-filename" value="qinglan-${Date.now().toString().slice(-6)}.ysvox.json"></label>`,[{label:'取消',action:closeModal},{label:'保存',primary:true,action:async()=>{const filename=($('save-filename') as HTMLInputElement).value;const r=await tool('save_project',{filename});closeModal();toast('已保存 '+r.path);}}]);
$('recover').onclick=()=>safe(async()=>{const files:string[]=await request('/api/files');modal('恢复原生项目',`<p>加载前会把当前文档另存为 before-load。自动保存支持重启恢复，后备快照保留上一次保存。</p><label>项目<select id="recover-file">${files.map(f=>`<option>${esc(f)}</option>`).join('')}</select></label>`,[{label:'取消',action:closeModal},{label:'加载项目',primary:true,action:async()=>{const filename=($('recover-file') as HTMLSelectElement).value;await request('/api/load',{filename,expectedVersion:project.version});closeModal();}}]);});
$('export').onclick=()=>modal('导出项目资产',`<p>输出视觉 GLB、开放体素 JSON、碰撞格、组件接口和材质图集。导出结果仍保留米制坐标与名称。</p><label>范围<select id="export-scope"><option value="scene">完整拼装场景</option><option value="asset">当前母版</option></select></label><label style="margin-top:12px">目录名称<input id="export-name" value="qinglan-${Date.now().toString().slice(-6)}"></label>`,[{label:'取消',action:closeModal},{label:'生成导出文件',primary:true,action:async()=>{const args:any={name:($('export-name') as HTMLInputElement).value};if(($('export-scope') as HTMLSelectElement).value==='asset')args.assetId=activeAsset;const result=await tool('export_project',args);modal('导出完成',`<p>${esc(result.directory)}</p><pre>${esc(result.files.join('\n'))}\nGLB ${result.glbBytes.toLocaleString()} bytes</pre>`);}}]);
$('geometry').onclick=()=>safe(async()=>{toast('后台检查碰撞、支撑和开口…');const report=await tool('check_geometry',{clearances:[{name:'入户通行净空',min:[.8,.6,-.6],max:[2.2,2.8,.4]}]});modal('几何检查',`<div class="impact"><div><b>${report.collisions.length}</b><small>碰撞对</small></div><div><b>${report.unsupported.length}</b><small>无下方支撑</small></div><div><b>${report.openings.length}</b><small>声明开口</small></div></div><pre>${esc(JSON.stringify(report,null,2))}</pre>`);});
$('help').onclick=()=>modal('从格子到可复用组件',`<p>1. 在左侧选择资产，点「编辑母版」；笔刷按面添加、擦除、取色，框选用两次点击。一次拖动是一笔可撤销命令。</p><p>2. 右侧参数重建、规则赋材质和变换都会先预览。选区坐标上界不包含在区域内。旋转以选区最小角为基准。</p><p>3. 拖资产到场景会按该格距吸附地面。精确放置与同接口拼接在「安装与实例」中。母版修改同步所有引用；「独立副本」可解除关联。</p><p>4. 导入选择 GLB / glTF / OBJ，可同时选伴随 BIN、图片或 MTL；先检查预算和几何，再转换并检查对照。任务完成前可取消。</p><p>5. MCP stdio 运行 npm run mcp，连接本机 4317 服务。界面和 MCP 使用同一版本、同一事务与撤销栈。</p>`);
$('viewport').ondragover=e=>e.preventDefault();$('viewport').ondrop=e=>{e.preventDefault();const id=e.dataTransfer!.getData('text/asset'),template=e.dataTransfer!.getData('text/template');if(template){newTemplate(template);return;}if(!id)return;void safe(async()=>{const a=project.assets[id],point=viewer.groundPoint(e as any)??[0,0,0];modal('放置组件',`<p>${esc(a.name)} · 吸附格距 ${a.cellSize}m</p><label>地面 X / Y / Z（米）</label><div class="triple">${[point[0],0,point[2]].map((v,i)=>`<input id="drop-${i}" type="number" step="${a.cellSize}" value="${v}">`).join('')}</div>`,[{label:'取消',action:closeModal},{label:'预览放置',primary:true,action:async()=>{const position=[0,1,2].map(i=>Math.round(Number(($('drop-'+i) as HTMLInputElement).value)/a.cellSize)*a.cellSize);closeModal();await edit([{op:'instance',id:'inst-'+crypto.randomUUID().slice(0,8),assetId:id,position,rotation:0}],'拖放组件',true);}}]);});};
function renderImport(){
 $('left-content').innerHTML=`<div class="pane"><h3>网格 → 可编辑体素</h3><p class="subtle">保留原件。可同时选择 glTF 伴随文件。先诊断，再选择转换策略。</p><input type="file" id="import-file" accept=".obj,.glb,.gltf,.bin,.png,.jpg,.jpeg,.mtl" multiple style="margin:14px 0;font-size:10px"><div class="field-stack"><label>格距（米）<input id="import-pitch" type="number" value="0.1" min="0.01" step="0.05" max="1"></label><label>源单位倍数<input id="import-scale" type="number" value="1" min="0.001" step="0.001"></label><label>源向上轴<select id="import-up"><option>Y</option><option>Z</option></select></label><label>原点 X / Y / Z（米）</label><div class="triple"><input id="import-ox" type="number" value="0"><input id="import-oy" type="number" value="0"><input id="import-oz" type="number" value="0"></div><label>体素化模式<select id="import-mode"><option value="surface">表面相交</option><option value="solid">封闭实体填充</option></select></label><label>颜色<select id="import-color"><option value="sample">采样源颜色 / 贴图</option><option value="uniform">当前材质（明确指定）</option></select></label><label>采样色量化<select id="import-levels"><option value="8">每通道 8 级 / 较少材质</option><option value="16">每通道 16 级 / 精细</option><option value="4">每通道 4 级 / 快速</option></select></label><label>薄片策略<select id="import-thin"><option value="conservative">保守相交 / 保留薄片</option><option value="center">中心距离 / 少膨胀</option></select></label><button id="inspect-source">1. 检查原件与预算</button><button id="convert-source" class="primary">2. 开始后台转换</button><button id="cancel-import">取消当前任务</button><progress id="import-progress" class="import-progress" max="1" value="0"></progress><div id="import-status" class="import-status muted">${sourceId?'原件已保存在本地项目目录':'尚未选择源文件'}</div><button id="commit-import">3. 预览提交为母版</button><button id="compare-import">原件 / 结果对照</button></div></div>`;
 $('import-file').onchange=e=>safe(async()=>{const files=[...(e.target as HTMLInputElement).files??[]],main=files.find(f=>/\.(obj|glb|gltf)$/i.test(f.name));if(!main)throw new Error('请选择 OBJ / GLB / glTF 主文件');const b64=async(f:File)=>{const bytes=new Uint8Array(await f.arrayBuffer());let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s);};const resources:Record<string,string>={};for(const f of files)if(f!==main)resources[f.name]=await b64(f);sourcePreview={filename:main.name,data:await b64(main),resources};const result=await request('/api/upload',sourcePreview);sourceId=result.sourceId;inspectResult=null;importResult=null;$('import-status').textContent=`已保留 ${main.name} / ${main.size.toLocaleString()} bytes`;});
 const options=()=>({sourceId,name:'导入模型',cellSize:Number(($('import-pitch') as HTMLInputElement).value),origin:['x','y','z'].map(k=>Number(($('import-o'+k) as HTMLInputElement).value)),scale:Number(($('import-scale') as HTMLInputElement).value),upAxis:($('import-up') as HTMLSelectElement).value,mode:($('import-mode') as HTMLSelectElement).value,colorMode:($('import-color') as HTMLSelectElement).value,colorLevels:Number(($('import-levels') as HTMLSelectElement).value),material:activeMaterial,thinPolicy:($('import-thin') as HTMLSelectElement).value,expectedVersion:project.version,requestId:crypto.randomUUID()});
 $('inspect-source').onclick=()=>safe(async()=>{if(!sourceId)throw new Error('先选择源文件');const args=options(),job=await request('/api/inspect',args);currentJob=job.id;await pollJob(job.id,true);});
 $('convert-source').onclick=()=>safe(async()=>{if(!inspectResult)throw new Error('请先检查原件与预算');const opts=options();if(['cellSize','scale','upAxis','origin'].some(k=>JSON.stringify((opts as any)[k])!==JSON.stringify(inspectResult.options?.[k]))){const check=await request('/api/inspect',opts);currentJob=check.id;await pollJob(check.id,true);if(!inspectResult)throw new Error('请先完成当前选项诊断');}modal('转换预算',`<p>当前格距 ${opts.cellSize}m。诊断不会修复粘连、开口或结构；请检查后开始转换。</p><pre>${esc(JSON.stringify(inspectResult.diagnostics,null,2))}</pre>`,[{label:'返回',action:closeModal},{label:'开始可取消任务',primary:true,action:async()=>{closeModal();const job=await tool('import_mesh',opts);currentJob=job.id;await pollJob(job.id,false);}}]);});
 $('cancel-import').onclick=()=>safe(async()=>{if(currentJob){const r=await tool('cancel_job',{jobId:currentJob});$('import-status').textContent=r.status;}});
 $('compare-import').onclick=()=>safe(()=>showComparison(inspectResult?.triangles??[],importResult?.asset,importResult?.materials,importResult?.comparison,inspectResult?.diagnostics));
 $('commit-import').onclick=()=>safe(async()=>{if(!importResult?.asset)throw new Error('没有完成的转换结果');const e={jobId:currentJob,expectedVersion:project.version,requestId:crypto.randomUUID()},r=await tool('commit_import',{...e,dryRun:true});modal('提交体素资产',`<p>${r.modifiedVoxels.toLocaleString()} 格 · ${importResult.performance.chunks} 块</p><pre>${esc(JSON.stringify(importResult.comparison,null,2))}</pre>`,[{label:'取消',action:closeModal},{label:'确认导入',primary:true,action:async()=>{await tool('commit_import',{...e,previewToken:r.previewToken});closeModal();toast('导入母版已加入组件库');}}]);});
}
async function pollJob(id:string,inspect:boolean){while(true){const job=await request('/api/job/'+id);const status=$('import-status'),progress=$<HTMLProgressElement>('import-progress');if(progress)progress.value=job.progress?.progress??0;if(status)status.textContent=job.status==='running'?`后台 ${inspect?'检查':'转换'}… ${Math.round((job.progress?.progress??0)*100)}%`:job.status;
 if(job.status!=='running'){if(job.status==='completed'){if(inspect){inspectResult={...job.result,options:job.options};await showComparison(job.result.triangles,undefined,undefined,undefined,job.result.diagnostics);if(status)status.textContent=`${job.result.diagnostics.triangles} 三角形\n${job.result.diagnostics.boundaryEdges} 开放边\n预算 ${job.result.diagnostics.estimatedGridCells.toLocaleString()} 格 / ${job.result.diagnostics.estimatedWorkingMemoryMB.toFixed(1)} MB\n${job.result.diagnostics.warnings.join('\n')}`;}else{importResult=job.result;if(status)status.textContent=`完成 ${job.result.performance.voxels.toLocaleString()} 格\n${job.result.performance.durationMs.toFixed(1)} ms\n${job.result.comparison.warnings.join('\n')}`;await showComparison(inspectResult.triangles,importResult.asset,importResult.materials,importResult.comparison,importResult.diagnostics);}}else if(status)status.textContent=job.error??'已取消，无文档修改';return;}await new Promise(r=>setTimeout(r,400));}}
await safe(async()=>{const params=new URLSearchParams(location.search),initial=await request('/api/state');
 if(params.get('library')==='1')tab='production';if(params.get('atlas')==='1')tab='atlas';if(/^M[0-9]{3}$/.test(params.get('sheet')??''))atlasPanel.sheet=params.get('sheet')!;
 if(params.has('preview'))document.body.classList.add('preview-mode');
 const requested=params.get('asset');if(requested&&initial.project.assets[requested]){activeAsset=requested;viewMode='asset';viewer.mode='asset';viewer.assetId=requested;}
 else if(initial.project.selection.assetId)activeAsset=initial.project.selection.assetId;
 if(tab==='atlas'){const source=initial.project.assets[activeAsset]?.source,referenceSheet=(source?.reference as any)?.sheet;if(typeof source?.catalogId==='string'&&/^M[0-9]{3}$/.test(referenceSheet??'')&&(!params.has('sheet')||atlasPanel.sheet===referenceSheet)){atlasPanel.sheet=referenceSheet;atlasPanel.selected=source.catalogId;}}
 appState.clay(params.get('flat')!=='0'&&params.get('material')!=='1');
 await applyState(initial);viewer.fit();if(viewMode==='asset')$('hint').innerHTML='笔刷 / 擦除可拖动 · 两点框选 · 右键平移<br>坐标是整数格 · 对称平面经过选区中心';$('sync').textContent='本地文档已同步';if(initial.recovery.recovered)toast('已恢复 '+initial.recovery.from);
 if(params.has('view')&&['perspective','isometric','front','back','left','right','top','bottom'].includes(params.get('view')!))changeView(params.get('view')!);
 if(params.get('look')==='reference')appState.referenceLighting(true);
 if(params.get('bloom')==='1')appState.bloom(true);if(params.get('ao')==='1')appState.ao(true);
});
let retry:any;function connect(){const ws=new WebSocket(`ws://${location.host}/ws`);ws.onopen=()=>{$('sync').textContent='本地文档已同步';$('connection').innerHTML='<i class="status-dot"></i>MCP · 本地共享文档';};ws.onmessage=e=>void safe(()=>applyState(JSON.parse(e.data)));ws.onclose=()=>{$('sync').textContent='连接中断 · 正在重连';retry=setTimeout(async()=>{await safe(async()=>applyState(await request('/api/state')));connect();},1500);};}connect();
